{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C27"],
      "claim": "Delpazolid, which shares the query's 5-(hydroxymethyl)oxazolidin-2-one core and 3-fluoro-4-aminophenyl attachment, had an absolute oral bioavailability of 99.75% in healthy male volunteers after an 800 mg oral dose versus IV, with dose-normalized AUC equivalence. This close structural analogy strongly supports high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C54"],
      "claim": "Linezolid, the prototypical oxazolidinone antibiotic, has essentially 100% absolute oral bioavailability in humans, demonstrating that the oxazolidinone scaffold is well absorbed orally and supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Milvexian under fasted conditions had an absolute bioavailability of 58.2% (95% CI 52.8–70.7%) at 25 mg relative to an IV microtracer, providing a direct human fasted-state absolute F value well above the 20% threshold and supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Ketanserin in fasted subjects had an absolute bioavailability of 60% after a 40 mg oral tablet versus IV, another fasted-condition human absolute F measurement above 20% that supports the query's high-bioavailability prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Zalcitabine in fasting patients had an absolute bioavailability of 80% (range 54–127%) for oral tablets, supporting high oral bioavailability for small, moderately polar molecules under fasting conditions.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferred experimental evidence points to high oral bioavailability: the closest structural analogue delpazolid (same oxazolidinone core) has ~100% absolute F, linezolid is ~100% bioavailable, and other high-transfer human absolute F values range from ~44% to ~100%, all above 20%. The physicochemical prior is also favorable. Therefore the query is predicted to have F >= 20%.",
  "evidence_gaps": [
    "No direct absolute bioavailability study for the query molecule itself is included in the evidence set.",
    "The query is the free-alcohol oxazolidinone, whereas some marketed oxazolidinones use prodrugs; direct data on the free alcohol form are not provided.",
    "Possible first-pass metabolism or transporter effects specific to the tetrazole-pyridine moiety are not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

